interface Customer { val name: String; val balance: Long }
class CustomerCore(override val name: String) : Customer {
    override var balance: Long = 0
    private val roles = mutableMapOf<KClass<*>, CustomerRole>()
    fun <T : CustomerRole> addRole(type: KClass<T>, role: T): T { roles[type] = role; return role }   // owns roles
    @Suppress("UNCHECKED_CAST") fun <T : CustomerRole> getRole(type: KClass<T>) = roles[type] as T?
}

abstract class CustomerRole(private val core: CustomerCore) : Customer by core   // forwarding generated
class BorrowerRole(core: CustomerCore) : CustomerRole(core) {
    fun borrow(amount: Long) = "$name borrows $amount"
}
